CREATE DEFINER=`user`@`%` PROCEDURE `fill_Q2_combo_stats_order`()
BEGIN
  DECLARE done INT DEFAULT 0;
  DECLARE a TINYINT;
  DECLARE b TINYINT;
  DECLARE last DATE;
  DECLARE freq INT;

  DECLARE cur CURSOR FOR
    SELECT n1, n2, MAX(Tirage), COUNT(*) FROM Q2_stats_order GROUP BY n1, n2;

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

  DELETE FROM Q2_combo_stats_order;

  OPEN cur;
  loop1: LOOP
    FETCH cur INTO a, b, last, freq;
    IF done THEN LEAVE loop1; END IF;

    INSERT INTO Q2_combo_stats_order (n1, n2, jours, tirage, max_fois)
    VALUES (a, b, DATEDIFF(CURDATE(), last), last, freq);
  END LOOP;
  CLOSE cur;
END ;;
DELIMITER ;
