CREATE DEFINER=`user`@`%` PROCEDURE `fill_Q3_combo_stats_order`()
BEGIN
  DECLARE done INT DEFAULT 0;
  DECLARE a, b, c TINYINT;
  DECLARE last DATE;
  DECLARE freq INT;

  DECLARE cur CURSOR FOR
    SELECT n1, n2, n3, MAX(Tirage), COUNT(*) 
    FROM Q3_stats_order 
    GROUP BY n1, n2, n3;

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

  DELETE FROM Q3_combo_stats_order;

  OPEN cur;
  loop1: LOOP
    FETCH cur INTO a, b, c, last, freq;
    IF done THEN LEAVE loop1; END IF;

    INSERT INTO Q3_combo_stats_order (n1, n2, n3, jours, tirage, max_fois)
    VALUES (a, b, c, DATEDIFF(CURDATE(), last), last, freq);
  END LOOP;
  CLOSE cur;
END ;;
DELIMITER ;
