CREATE DEFINER=`user`@`%` PROCEDURE `fill_Q3_stats_norder`()
BEGIN
    DECLARE d DATE;
    DECLARE a INT;
    DECLARE b INT;
    DECLARE c INT;
    DECLARE x INT;
    DECLARE y INT;
    DECLARE z INT;

    -- Получаем последний тираж
    SELECT Tirage, n1, n2, n3 INTO d, a, b, c
    FROM Q3
    ORDER BY Tirage DESC
    LIMIT 1;

    -- Упорядочиваем числа
    SET x = LEAST(a, b, c);
    SET z = GREATEST(a, b, c);
    SET y = a + b + c - x - z;

    -- Вставляем строку статистики, если ещё не существует
    INSERT IGNORE INTO Q3_stats_norder (Tirage, n1, n2, n3, days, days2, fois, max)
    SELECT 
        d,
        a,
        b,
        c,

        -- days
        IFNULL(DATEDIFF(d, (
            SELECT MAX(Tirage) FROM Q3
            WHERE Tirage < d 
              AND LEAST(n1, n2, n3) = x
              AND GREATEST(n1, n2, n3) = z
              AND (n1 + n2 + n3 - LEAST(n1, n2, n3) - GREATEST(n1, n2, n3)) = y
        )), 0),

        -- days2
        IFNULL(DATEDIFF((
            SELECT MAX(Tirage) FROM Q3
            WHERE Tirage < (
                SELECT MAX(Tirage) FROM Q3
                WHERE Tirage < d
                  AND LEAST(n1, n2, n3) = x
                  AND GREATEST(n1, n2, n3) = z
                  AND (n1 + n2 + n3 - LEAST(n1, n2, n3) - GREATEST(n1, n2, n3)) = y
            )
              AND LEAST(n1, n2, n3) = x
              AND GREATEST(n1, n2, n3) = z
              AND (n1 + n2 + n3 - LEAST(n1, n2, n3) - GREATEST(n1, n2, n3)) = y
        ), (
            SELECT MAX(Tirage) FROM Q3
            WHERE Tirage < d
              AND LEAST(n1, n2, n3) = x
              AND GREATEST(n1, n2, n3) = z
              AND (n1 + n2 + n3 - LEAST(n1, n2, n3) - GREATEST(n1, n2, n3)) = y
        )), 0),

        -- fois
        IFNULL((
            SELECT COUNT(*) FROM Q3
            WHERE Tirage <= d 
              AND LEAST(n1, n2, n3) = x
              AND GREATEST(n1, n2, n3) = z
              AND (n1 + n2 + n3 - LEAST(n1, n2, n3) - GREATEST(n1, n2, n3)) = y
        ), 0),

        -- max
        IFNULL((
            SELECT MAX(DATEDIFF(Tirage, prev_Tirage)) FROM (
                SELECT Tirage,
                       LAG(Tirage) OVER (
                           PARTITION BY 
                               LEAST(n1, n2, n3), 
                               GREATEST(n1, n2, n3), 
                               (n1 + n2 + n3 - LEAST(n1, n2, n3) - GREATEST(n1, n2, n3))
                           ORDER BY Tirage
                       ) AS prev_Tirage
                FROM Q3
                WHERE Tirage <= d
                  AND LEAST(n1, n2, n3) = x
                  AND GREATEST(n1, n2, n3) = z
                  AND (n1 + n2 + n3 - LEAST(n1, n2, n3) - GREATEST(n1, n2, n3)) = y
            ) AS temp
            WHERE prev_Tirage IS NOT NULL
        ), 0);
END ;;
DELIMITER ;
